using System; using System.Linq; using System.Text.RegularExpressions;
public static class StringReadability { private static readonly Regex Words=new("[A-Z][a-z]*"); public static string FromPascalCase(string value)=>string.Concat(Words.Matches(value).Cast<Match>().Select(m=>m.Value.All(char.IsUpper)?m.Value:m.Value.ToLower())); public static string Dehumanize(string value)=>string.Concat(value.Split(' ').Select(word=>char.ToUpper(word[0])+word[1..])); public static string Transform(this string value,params Func<string,string>[] transforms)=>transforms.Aggregate(value,(text,transform)=>transform(text)); }
